import type { DescribeChangeSetCommandOutput } from '@aws-sdk/client-cloudformation';
import { ToolkitError } from '../../toolkit/toolkit-error';
import type { ResourceDeleteFailure, StabilizingResource } from '../../toolkit/types';

export type DeployStackResult =
  | SuccessfulDeployStackResult
  | NeedRollbackFirstDeployStackResult
  | ReplacementRequiresRollbackStackResult
  ;

/** Successfully deployed a stack */
export interface SuccessfulDeployStackResult {
  readonly type: 'did-deploy-stack';
  readonly noOp: boolean;
  readonly outputs: { [name: string]: string };
  readonly stackArn: string;

  /**
   * The change set that was created during deployment, if any.
   * Populated when using `change-set` deployment method with `execute: false`.
   */
  readonly changeSet?: DescribeChangeSetCommandOutput;

  /**
   * Resources that CloudFormation failed to delete during the stack update.
   * Non-empty only for stack updates where CFN skipped deletion failures.
   */
  readonly deleteFailures: ResourceDeleteFailure[];

  /**
   * Resources that completed deployment but are still stabilizing.
   * Non-empty only for Express Mode deployments where CloudFormation reported
   * resources as complete with a stabilization status reason.
   */
  readonly stabilizingResources: StabilizingResource[];
}

/** The stack is currently in a failpaused state, and needs to be rolled back before the deployment */
export interface NeedRollbackFirstDeployStackResult {
  readonly type: 'failpaused-need-rollback-first';
  readonly reason: 'not-norollback' | 'replacement';
  readonly status: string;
}

/** The upcoming change has a replacement, which requires deploying with --rollback */
export interface ReplacementRequiresRollbackStackResult {
  readonly type: 'replacement-requires-rollback';
}

export function assertIsSuccessfulDeployStackResult(x: DeployStackResult): asserts x is SuccessfulDeployStackResult {
  if (x.type !== 'did-deploy-stack') {
    throw new ToolkitError('UnexpectedDeployResult', `Unexpected deployStack result. This should not happen: ${JSON.stringify(x)}. If you are seeing this error, please report it at https://github.com/aws/aws-cdk/issues/new/choose.`);
  }
}
